"""Shared geometry plus distinct C/I visual skins for the Human Decision Surface."""

def styles(surface,theme):
 css='''*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:18px}body{margin:0;background:#06101a;color:#d9e4e9;font:16px ui-monospace,monospace}main{min-height:100vh;display:grid;grid-template-columns:190px 1fr}nav{border-right:1px solid #29485b;padding:28px 16px;display:flex;flex-direction:column;gap:10px;position:sticky;top:0;height:100vh;align-self:start}nav b{font:800 20px Arial;margin-bottom:28px}nav a{padding:12px;font-size:16px;color:#8da2ae}.content{padding:28px;width:100%;max-width:none;min-width:0}.hero{border-top:2px solid #e0bd45;padding-top:14px}.hero h1{font:800 60px Arial;margin:6px 0 18px}.metrics{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;max-width:760px}.metrics>b{min-width:0;background:#0a1925;padding:10px 12px;font-size:24px}.metrics small{display:block;font-size:10px;color:#8da2ae}section{margin:0 0 72px 0;padding:14px 0;scroll-margin-top:24px}section+section{padding-top:24px}h2{font-size:16px;letter-spacing:.15em;color:#8da2ae;border-bottom:1px solid #29485b;padding-bottom:7px}.notice,.row,.provider,.quiet{background:#091722;border-bottom:1px solid #203b4d;padding:20px;display:grid;gap:11px}.notice{grid-template-columns:140px 1fr}.notice small,.notice .decision{grid-column:2;color:#8da2ae}.decision{display:flex;gap:6px}.decision form{margin:0}.lv4,.lv5{border-left:2px solid #c44348}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(310px,1fr));gap:16px}.provider span,.credential span,.route span,.hint{color:#8da2ae}.provider-name{font:800 26px Arial,sans-serif!important;letter-spacing:.02em;color:#e5f1f5}.provider-meta{font-size:13px}.provider-limits{display:flex;gap:24px;align-items:end;margin-top:6px}.limit{display:grid;grid-template-columns:auto auto;column-gap:10px;align-items:baseline}.limit>span{font-size:11px;letter-spacing:.08em}.limit>strong{font:800 28px Arial,sans-serif;color:#d9e4e9}.limit>small{grid-column:2;font-size:10px;color:#56c7d9}.provider-status{font-weight:700}.provider-issue{color:#f28a3a}.provider-note{color:#56c7d9}.quota{font-size:24px;color:#d9e4e9}.quota small{font-size:12px;color:#e0bd45}.credential{background:#091722;border-bottom:1px solid #203b4d;padding:14px;display:grid;grid-template-columns:minmax(120px,180px) minmax(140px,1fr) minmax(360px,auto);gap:12px;align-items:center}.credential small{grid-column:1 / 3;color:#8da2ae}.credential .decision{grid-column:3;grid-row:1 / span 2;display:grid;grid-template-columns:auto minmax(180px,260px) auto;gap:8px;align-items:center}.credential .decision form{display:contents}.credential .field-password{width:100%;min-width:0}.credential .decision .ui-button{white-space:nowrap;width:auto}.route{background:#091722;border-bottom:1px solid #203b4d;padding:20px;display:grid;grid-template-columns:160px 1fr 2fr;gap:8px}input,select,.ui-button{background:#0c1d29;color:#d9e4e9;border:1px solid #31566d;padding:12px;font-size:16px}.ui-button{min-height:44px;line-height:1.15;font-weight:700;letter-spacing:.04em}.ui-action{margin:0;display:inline-flex}.role-danger{}.role-confirm{}.role-secondary{}.ui-panel{overflow-wrap:anywhere}.provider input{width:100%}.design-switch{display:flex;justify-content:flex-end;margin-bottom:10px}.task{display:flex;margin-top:8px}.task input[name=task]{flex:1;min-width:0}.content,.notice,.row,.provider,.credential,.route,.telemetry{overflow-wrap:anywhere}.cards,.routes{min-width:0}.scroll-tail{height:58vh;min-height:420px}.provider,.route{position:relative}.health-online:after{content:'';position:absolute;right:10px;top:10px;width:5px;height:5px;border-radius:50%;background:currentColor;opacity:.55}.health-online:hover:after{animation:provider-pulse .9s ease-out 1}.ui-button{transition:filter .12s ease,box-shadow .12s ease,transform .08s ease}.ui-button:hover{filter:brightness(1.12)}.ui-button:active{transform:translateY(1px);filter:brightness(.94)}.ui-button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid currentColor;outline-offset:2px}@keyframes provider-pulse{0%{opacity:.35;box-shadow:0 0 0 0 currentColor}100%{opacity:.8;box-shadow:0 0 0 8px transparent}}.route-active{animation:route-live 2s cubic-bezier(.45,0,.2,1) infinite}.compute-active{animation:compute-live 2s cubic-bezier(.45,0,.2,1) infinite}.ui-button{position:relative;overflow:hidden}.ui-button:active:after{content:'';position:absolute;inset:0;background:currentColor;opacity:.12;animation:control-confirm .18s ease-out 1}@keyframes route-live{0%,100%{filter:brightness(1)}50%{filter:brightness(1.42)}}@keyframes compute-live{0%,100%{filter:brightness(1);transform:translateY(0)}50%{filter:brightness(1.35);transform:translateY(-2px)}}@keyframes control-confirm{from{opacity:.22}to{opacity:0}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}@media(max-width:900px){main{grid-template-columns:150px minmax(0,1fr)}.content{padding:20px}.credential{grid-template-columns:120px minmax(0,1fr)}.credential small{grid-column:1 / 3}.credential .decision{grid-column:1 / 3;grid-row:auto;grid-template-columns:auto minmax(160px,1fr) auto}.route{grid-template-columns:minmax(100px,140px) minmax(0,1fr)}}@media(max-width:700px){main{grid-template-columns:1fr}nav{position:sticky;top:0;z-index:10;height:auto;align-self:stretch;display:flex;flex-direction:row;overflow-x:auto;overflow-y:hidden;max-width:100vw;min-width:0;padding:8px;gap:4px;border-right:0;border-bottom:1px solid #29485b;white-space:nowrap;-webkit-overflow-scrolling:touch}nav b{margin:0 8px 0 0;display:flex;align-items:center;flex:0 0 auto}nav a{flex:0 0 auto;padding:10px}.content{padding:16px}.hero h1{font-size:38px}.notice{grid-template-columns:1fr}.notice small,.notice .decision{grid-column:1}.metrics{grid-template-columns:repeat(5,minmax(56px,1fr));overflow-x:auto}.metrics>b{min-width:56px}.task{display:grid}.credential{grid-template-columns:1fr}.credential small,.credential .decision{grid-column:1}.credential .decision{grid-template-columns:1fr}.credential .decision form{display:block}.credential .decision .ui-button,.credential .field-password{width:100%}}'''
 css+='''.paid-hop{color:#d85f4b!important;border-color:#d85f4b!important}.route-path{display:flex;align-items:center;flex-wrap:wrap;gap:6px;margin-top:10px;font-size:13px}.route-hop{font-weight:700}.route-arrow{opacity:.55}.route-cost-status b{color:#d85f4b}'''
 css+='.overview-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr));gap:10px;margin-top:14px}.flow{display:grid;gap:10px;margin-top:14px}.flow-row{display:flex;align-items:stretch;gap:8px;flex-wrap:wrap}.flow-node{display:grid;gap:8px;padding:16px;background:rgba(77,111,132,.11);border:1px solid #31566d;text-decoration:none;color:inherit;min-width:0;overflow-wrap:anywhere;flex:1 1 180px;align-content:start}.flow-node:hover,.flow-node:focus-visible{border-color:currentColor}.flow-node span{color:#8da2ae}.flow-branch{display:grid;gap:8px;flex:2 1 340px}.flow-arrow{align-self:center;color:#8da2ae}.flow-node.live{animation:route-live 2s cubic-bezier(.45,0,.2,1) infinite}.flow-node.waiting{border-left:2px solid #c44348}.flow-caption{color:#8da2ae;letter-spacing:.12em;font-size:13px}.flow-expl{color:#d9e4e9;font-size:14px}.telemetry{display:grid;gap:11px}.flow-svg{display:block;width:100%;max-width:560px;height:auto;margin:14px auto 0}.flow-svg text{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}.flow-svg-node.live{animation:route-live 2s cubic-bezier(.45,0,.2,1) infinite}.flow-svg-node.live circle{animation:route-live 2s cubic-bezier(.45,0,.2,1) infinite}.flow-svg-node.live rect{stroke:#56c7d9;stroke-width:2.5}details.fold{margin-top:26px}details.fold>summary{cursor:pointer;color:#d9e4e9;font-weight:700;letter-spacing:.08em;padding:10px 0;border-bottom:1px solid #31566d}.flow-details{margin-top:12px}.flow-details small{display:block;color:#8da2ae;margin-top:6px}.overview-tile{display:grid;gap:8px;padding:16px;background:rgba(77,111,132,.11);border:1px solid #31566d;text-decoration:none;color:inherit;min-width:0;overflow-wrap:anywhere}.overview-tile:hover,.overview-tile:focus-visible{border-color:currentColor}.overview-tile small{color:#8da2ae;letter-spacing:.08em}.overview-tile strong{font-size:20px}.overview-tile span{color:#8da2ae;font-size:12px;line-height:1.5}'+''
 echo=surface=='echo'

 if echo: css+='.scroll-tail{display:none}body{font-size:13px}nav b{font-size:16px}nav a{font-size:13px}h2{font-size:13px}.quota{font-size:18px}.quota small{font-size:9px}html{scroll-padding-top:8px}main{grid-template-columns:minmax(112px,145px) minmax(0,1fr)}.content{padding:14px}.hero h1{font-size:36px}.hero{margin-bottom:12px}section{margin:0 0 24px 0}section+section{padding-top:6px}.health-online:hover:after{animation:none}@media(max-width:600px){main{grid-template-columns:1fr}nav{display:none}.content{padding:12px}.hero h1{font-size:32px}.cards{grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr))}}'
 # Themes share geometry/content/typographic metrics, not visual design language.
 if theme=='C':
  css+=':root{--theme:C}body{background:#101310;color:#e9ede8}nav{background:linear-gradient(180deg,#171b17,#0d100d);border-color:#343b34}nav b{color:#f1f3ee}nav a{color:#adb5ad}.hero{border-color:#d8df27}.hero h1{color:#f3f5f0;text-shadow:10px 0 24px #5e651f}.metrics>b{background:linear-gradient(105deg,#272c27,#171b17);border-bottom:2px solid #d8df27}.metrics small,.provider span,.credential span,.route span,.hint{color:#9fa89f}h2{color:#d8df27;border-color:#454d45}.notice,.row,.provider,.quiet,.credential,.route,.telemetry{background:linear-gradient(110deg,#232823,#171b17);border-bottom-color:#424a42}.cards .provider{box-shadow:inset 3px 0 #d8df27,inset 0 1px #343b34;background-image:linear-gradient(90deg,#2b302b 0,#202520 72%,#181c18 100%)}.routes .route{box-shadow:inset 3px 0 #7b847b,inset 0 -1px #343b34;background-image:linear-gradient(90deg,#222722,#181c18)}input,select{background:#202520;color:#e9ede8;border-color:#3e473e;box-shadow:inset 0 -2px #d8df27}input::placeholder{color:#7f897f}select{color:#dce2da}.ui-button{background:#d8df27;color:#111410;border-color:transparent;box-shadow:inset 0 -2px #747918}.role-secondary{background:#272d27;color:#e9ede8;box-shadow:inset 0 -2px #d8df27}.role-danger{background:#e58a3f;color:#111410}.role-confirm{background:#d8df27;color:#111410}.quota{color:#f4f6f1}.quota small{color:#d8df27}.lv1{border-left-color:#7f897f}.lv2{border-left-color:#9fa89f}.lv3{border-left-color:#d8df27}.lv4{border-left-color:#e58a3f}.lv5{border-left-color:#e45656}.design-switch .ui-button{background:#272d27;color:#e9ede8;box-shadow:inset 0 -2px #d8df27;text-shadow:8px 0 18px #596018}.route-active{box-shadow:inset 3px 0 #d8df27,inset 0 -2px #d8df27}.compute-active{box-shadow:inset 3px 0 #d8df27,0 0 14px #596018}'
 else:
  css+=':root{--theme:I}body{background:radial-gradient(circle at 82% 8%,#0c2333 0,#06101a 36%,#040b12 100%);color:#d9e4e9}nav{background:linear-gradient(180deg,#07131e,#050d15);border-color:#29485b}nav b{color:#dcebf2;text-shadow:0 0 14px #2d6c8c}nav a{color:#8da2ae}.hero{border-color:#e0bd45}.hero h1{color:#e5f1f5;text-shadow:0 0 22px #245a77}.metrics>b{background:#0a1925;box-shadow:inset 0 1px #24475b,inset 0 -1px #102b3c}.metrics>b:nth-child(1){box-shadow:inset 0 -2px #e45656}.metrics>b:nth-child(2){box-shadow:inset 0 -2px #f28a3a}.metrics>b:nth-child(3){box-shadow:inset 0 -2px #e8c64b}.metrics>b:nth-child(4){box-shadow:inset 0 -2px #56c7d9}.metrics>b:nth-child(5){box-shadow:inset 0 -2px #6d8796}.metrics small,.provider span,.credential span,.route span,.hint{color:#8da2ae}h2{color:#8da2ae;border-color:#29485b}.notice,.row,.provider,.quiet,.credential,.route,.telemetry{background:linear-gradient(180deg,#0a1925,#08141e);border-bottom-color:#203b4d}.cards .provider{box-shadow:inset 2px 0 #56c7d9,inset 0 1px #28495c;background-image:linear-gradient(90deg,#0d2030,#08141e 78%)}.routes .route{box-shadow:inset 2px 0 #e8c64b,inset 0 1px #203b4d;background-image:linear-gradient(90deg,#0c1b28,#08131d)}input,select,.ui-button{background:#0c1d29;color:#d9e4e9;border-color:#31566d;box-shadow:0 0 0 transparent}.role-confirm{border-color:#56c7d9;box-shadow:inset 2px 0 #56c7d9}.role-danger{border-color:#f28a3a;box-shadow:inset 2px 0 #f28a3a}.role-secondary{border-color:#31566d}.quota{color:#d9e4e9}.quota small{color:#56c7d9}.lv4{border-left-color:#f28a3a}.lv5{border-left-color:#e45656}.notice.lv4{box-shadow:inset 0 -1px #6f4428}.notice.lv5{box-shadow:inset 0 -1px #6b3030}.design-switch .ui-button{background:#0b2130;color:#b9dce6;border-color:#31566d;box-shadow:inset 2px 0 #56c7d9,inset 0 -1px #e8c64b}.route-active{box-shadow:inset 2px 0 #56c7d9,inset 0 -2px #e8c64b,0 0 12px #173f55}.compute-active{box-shadow:inset 2px 0 #56c7d9,0 0 16px #1f617d}'

 # Approved UI-only delta (2026-09-20). Do not alter existing palette/layout/components.
 if theme=='C':
  css+="body{background-image:linear-gradient(rgba(216,223,39,.025) 1px,transparent 1px),linear-gradient(90deg,rgba(216,223,39,.018) 1px,transparent 1px)!important;background-size:40px 40px!important}.hero{border-top:0!important;box-shadow:none!important;padding-top:14px!important;position:relative!important}.hero>small:first-child{display:block!important;padding-top:0!important;margin-top:0!important;transform:none!important}.hero>small:first-child~*{transform:none!important}.hero:before{content:''!important;position:absolute!important;left:0!important;right:0!important;top:-2px!important;height:16px!important;margin:0!important;background:repeating-linear-gradient(155deg,#d8df27 0 10px,transparent 10px 22px)!important;border:0!important;box-shadow:none!important;outline:0!important}.hero>small:first-child:before,.hero>small:first-child:after{display:none!important}h2{border-bottom:5px double #596253!important}"
 else:
  css+="h2{border-bottom:4px double #244858!important}"

 return css
